@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/assessment>
    a owl:Ontology ;
    rdfs:label "Educational Assessment Ontology"@en ;
    rdfs:comment "An ontology formalizing educational assessment, evaluation concepts, psychometric qualities, and testing methods."@en .

#################################################################
#    Root Domain Class
#################################################################

ea:AssessmentEntity
    a owl:Class ;
    rdfs:subClassOf owl:Thing ;
    rdfs:label "Assessment Entity"@en .

ea:Assessment
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentEntity ;
    rdfs:label "Assessment"@en ;
    skos:altLabel "Educational Assessment"@en , "Educational Evaluation"@en .

ea:AssessmentAxisValue
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentEntity ;
    rdfs:label "Assessment Axis Value"@en .

#################################################################
#    Axis 1: Purpose
#################################################################

ea:AssessmentPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentAxisValue ;
    rdfs:label "Assessment Purpose"@en ;
    owl:disjointUnionOf (
        ea:PlacementPurpose
        ea:FormativePurpose
        ea:SummativePurpose
        ea:DiagnosticPurpose
        ea:ScreeningPurpose
        ea:InterimPurpose
    ) .

ea:PlacementPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Placement Purpose"@en .

ea:FormativePurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Formative Purpose"@en .

ea:SummativePurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Summative Purpose"@en .

ea:DiagnosticPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Diagnostic Purpose"@en .

ea:ScreeningPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Screening Purpose"@en .

ea:InterimPurpose
    a owl:Class ;
    rdfs:subClassOf ea:AssessmentPurpose ;
    rdfs:label "Interim Purpose"@en .

ea:hasPurpose
    a owl:ObjectProperty ;
    rdfs:label "has purpose"@en ;
    rdfs:domain ea:Assessment ;
    rdfs:range ea:AssessmentPurpose ;
    owl:inverseOf ea:isPurposeOf .

ea:isPurposeOf
    a owl:ObjectProperty ;
    rdfs:label "is purpose of"@en ;
    rdfs:domain ea:AssessmentPurpose ;
    rdfs:range ea:Assessment .

ea:PlacementAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Placement Assessment"@en ;
    skos:altLabel "Initial Assessment"@en , "Pre-Assessment"@en , "Threshold Knowledge Test"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ]
        )
    ] .

ea:FormativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Formative Assessment"@en ;
    skos:altLabel "Assessment for Learning"@en , "Classroom Assessment"@en , "Educative Assessment"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ]
        )
    ] .

ea:SummativeAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Summative Assessment"@en ;
    skos:altLabel "Assessment of Learning"@en , "Summative Evaluation"@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ]
        )
    ] .

ea:DiagnosticAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment , ea:FormativeAssessment ;
    rdfs:label "Diagnostic Assessment"@en ;
    skos:altLabel "Diagnostic Evaluation"@en , "Diagnostic Testing"@en ;
    rdfs:comment "Corpus tension: One passage lists placement, formative, summative, and diagnostic assessments as coordinate categories, implying mutual exclusion in an enumerated partition, whereas another passage explicitly states that 'A common form of formative assessment is diagnostic assessment'. Both claims are asserted per instructions."@en ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            ea:Assessment
            [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ]
        )
    ] .

ea:ScreeningAssessment
    a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Screening Assessment"@en ;
    owl:equivalentClass [
        a owl:Class ;
